#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);

    size_t pos = s.find("at");
    if (pos != std::string::npos) {
        s.replace(pos, 2, "@");
    }

    size_t dot_pos = s.find("dot");
    while (dot_pos != std::string::npos) {
        s.replace(dot_pos, 3, ".");
        dot_pos = s.find("dot");
    }

    if (!s.empty() && s[0] == '.') {
        s = "dot" + s.substr(1);
    }

    if (!s.empty() && s[0] == '@') {
        size_t at_pos = s.find("at");
        if (at_pos != std::string::npos && at_pos == 0) {
            s.replace(at_pos, 2, "@");
            s = "at" + s.substr(2);
        }
    }

    if (!s.empty() && s.back() == '.') {
        s.back() = 'd';
        s += "ot";
    }

    std::cout << s << std::endl;
    return 0;
}

